"C:\\Program Files\\WindowsApps\\Microsoft.PowerShell_7.6.5.0_x64__8wekyb3d8bbwe\\pwsh.exe" -NoProfile -Command '$trxPath = '"'C:\\Users\\kingd\\AppData\\Local\\Temp\\grok-goal-0150143b1dcc\\implementer\\ledger\\21e5b43f\\c12-release.trx'
"'$logPath = '"'C:\\Users\\kingd\\AppData\\Local\\Temp\\grok-goal-0150143b1dcc\\implementer\\ledger\\21e5b43f\\c12-release.log'
"'$xml = [System.Xml.XmlDocument]::new()
$xml.Load($trxPath)
$allResults = @($xml.SelectNodes("/*[local-name()='"'TestRun']/*[local-name()='Results']/*[local-name()='UnitTestResult']\"))
"'$outcomeGroups = @($allResults | Group-Object { [string]$_.GetAttribute('"'outcome') } | Sort-Object Name | ForEach-Object {
  [ordered]@{ Outcome = "'$_.Name; Count = $_.Count }
})
$targetChecks = @(
  [ordered]@{
    Label = '"'TwentyFourth ExactFinal'
    Matches = @("'$allResults | Where-Object { ([string]$_.GetAttribute('"'testName')) -eq 'McpServer.Support.Mcp.Tests.Documentation.BugTriage139TwentyFourthEvidenceTests.ExactFinalEvidenceTag_BindsRequiredBaseCandidateTreeAndCommandReceipts' } | ForEach-Object { [ordered]@{ TestName = [string]"'$_.GetAttribute('"'testName'); Outcome = [string]"'$_.GetAttribute('"'outcome') } })
  }
  [ordered]@{
    Label = 'FeatureHistory'
    Matches = @("'$allResults | Where-Object { ([string]$_.GetAttribute('"'testName')) -eq 'McpServer.Support.Mcp.Tests.Documentation.BugTriage139EleventhRepositoryAuditTests.FeatureHistory_ContainsExactlyOneFormalAdjacentAiTrailerPairPerCommit' } | ForEach-Object { [ordered]@{ TestName = [string]"'$_.GetAttribute('"'testName'); Outcome = [string]"'$_.GetAttribute('"'outcome') } })
  }
  [ordered]@{
    Label = 'SQL MigrateDown'
    Matches = @("'$allResults | Where-Object { ([string]$_.GetAttribute('"'testName')) -eq 'McpServer.Support.Mcp.Tests.Storage.SqlServerRenameQuadBrainRolesMigrationTests.MigrateDown_RenameQuadBrainRoles_RestoresLegacyHemisphereRows' } | ForEach-Object { [ordered]@{ TestName = [string]"'$_.GetAttribute('"'testName'); Outcome = [string]"'$_.GetAttribute('"'outcome') } })
  }
)
"'$exitMatches = @(Select-String -LiteralPath $logPath -SimpleMatch '"'C12_EXIT=0')
"'$porcelain = @(git --no-optional-locks -c core.fsmonitor=false status --porcelain=v1 --untracked-files=all)
[ordered]@{
  TrxSha256AfterParse = (Get-FileHash -LiteralPath $trxPath -Algorithm SHA256).Hash
  OutcomeGroups = $outcomeGroups
  NonPassedResultCount = @($allResults | Where-Object { ([string]$_.GetAttribute('"'outcome')) -ne 'Passed' }).Count
  TargetChecks = "'$targetChecks
  LogC12ExitZeroMatchCount = $exitMatches.Count
  LogC12ExitZeroMatches = @($exitMatches | ForEach-Object { [ordered]@{ LineNumber = $_.LineNumber; Line = $_.Line.Trim() } })
  FinalHead = git rev-parse --verify HEAD
  FinalTree = git rev-parse --verify '"'HEAD"'^{tree}'"'
  FinalTagPeel = git rev-parse --verify 'refs/tags/BUG-TRIAGE-139-twenty-fourth-exact-final"'^{}'"'
  FinalPorcelainCount = "'$porcelain.Count
  FinalPorcelain = $porcelain
} | ConvertTo-Json -Depth 8'

